const task = $json.data;

if (!task?.id) {
  throw new Error(
    'Directus no devolvió una tarea válida'
  );
}

function contactLabel(contact) {
  if (!contact) {
    return 'Sin contacto';
  }

  const name = [
    contact.first_name,
    contact.last_name
  ]
    .filter(Boolean)
    .join(' ')
    .trim();

  if (contact.company && name) {
    return `${contact.company} · ${name}`;
  }

  return (
    contact.company ||
    name ||
    'Sin contacto'
  );
}

function dueState(task) {
  if (
    task.status === 'completed' ||
    task.completed_at
  ) {
    return {
      state: 'completed',
      label: 'Completada'
    };
  }

  if (
    task.status === 'cancelled'
  ) {
    return {
      state: 'cancelled',
      label: 'Cancelada'
    };
  }

  if (!task.due_at) {
    return {
      state: 'no_due_date',
      label: 'Sin fecha'
    };
  }

  const now = new Date();
  const due = new Date(
    task.due_at
  );

  if (
    Number.isNaN(
      due.getTime()
    )
  ) {
    return {
      state: 'invalid_due_date',
      label: 'Fecha inválida'
    };
  }

  if (
    due.getTime() <
    now.getTime()
  ) {
    return {
      state: 'overdue',
      label: 'Retrasada'
    };
  }

  const sameDay =
    due.getFullYear() === now.getFullYear() &&
    due.getMonth() === now.getMonth() &&
    due.getDate() === now.getDate();

  if (sameDay) {
    return {
      state: 'today',
      label: 'Hoy'
    };
  }

  return {
    state: 'upcoming',
    label: 'Próxima'
  };
}

const timing = dueState(task);
const contact = task.contact_id;

return [
  {
    json: {
      status: 'resolved',

      task: {
        id:
          task.id,

        title:
          task.title ?? null,

        description:
          task.description ?? null,

        status:
          task.status ?? null,

        priority:
          task.priority ?? null,

        due_at:
          task.due_at ?? null,

        due_state:
          timing.state,

        due_label:
          timing.label,

        completed_at:
          task.completed_at ?? null,

        source:
          task.source ?? null,

        created_at:
          task.created_at ?? null,

        updated_at:
          task.updated_at ?? null
      },

      contact: contact
        ? {
            id:
              contact.id,

            first_name:
              contact.first_name ?? null,

            last_name:
              contact.last_name ?? null,

            company:
              contact.company ?? null,

            email:
              contact.email ?? null,

            status:
              contact.status ?? null,

            label:
              contactLabel(contact)
          }
        : null
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const taskId = clean(
  input.task_id
);

if (!taskId) {
  throw new Error(
    'task_id es obligatorio'
  );
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(taskId)) {
  throw new Error(
    `task_id no es un UUID válido: ${taskId}`
  );
}

return [
  {
    json: {
      task_id: taskId
    }
  }
];
